3825			tp->rx_opt.rcv_tsval = ntohl(*ptr);
3826			++ptr;
3827			if (*ptr)
3828				tp->rx_opt.rcv_tsecr = ntohl(*ptr) - tp->tsoffset;
3829			else
3830				tp->rx_opt.rcv_tsecr = 0;
